            aWandererC = aWandererC ^ (((RotL64(aScatter, 5U) + RotL64(aOrbiterB, 29U)) + aOrbiterA) + aWandererUpdateSaltE[((aIndex + 8U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aIngress, 29U) + RotL64(aOrbiterJ, 19U)) + aOrbiterD);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 54U) + aOrbiterE) + RotL64(aOrbiterA, 23U));
