            aOrbiterJ = (aWandererJ + RotL64(aPrevious, 47U)) + 0x33E1ACD5D954C80AULL;
            aOrbiterC = ((aWandererD + RotL64(aIngress, 37U)) + 0x1EFADE17F34ADBF5ULL) + aOrbiterAssignSaltF[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterE = (((aWandererC + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x114CCBF2ADC37A94ULL) + aNonceWordK;
            aOrbiterF = ((aWandererH + RotL64(aCross, 3U)) + RotL64(aCarry, 3U)) + 0x6BC73BAAF22706AEULL;
            aOrbiterB = (aWandererG + RotL64(aIngress, 10U)) + 0x126F6AE1875E0887ULL;
