            aOrbiterC = RotL64((aOrbiterC * 0xC8D20BCADAFEAC89ULL), 23U);
            //
            aOrbiterE = (((aOrbiterE + aOrbiterC) + 0xF5C4780F5F3661E1ULL) + aOrbiterUpdateSaltF[(((31U - aIndex) + 12U)) & S_SALT1]) + aNonceWordC;
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0xD8FE2ED773DB315FULL) ^ aNonceWordJ;
            aOrbiterI = RotL64((aOrbiterI * 0x5C41D41EA77F3DB1ULL), 53U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0xD9F2CDA89226CCFBULL) + aOrbiterUpdateSaltA[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xA2D933B5D811477DULL;
            aOrbiterF = RotL64((aOrbiterF * 0xF98DF862D01B1BC5ULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x0962F4D756647E41ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xEF6E14585ADA9C42ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0C9FD9B54246E943ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x350CD354FD03C97DULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xD84B902E5A124B78ULL) ^ aOrbiterUpdateSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xCF256B01D69032F9ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xC1B105854ABA622DULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x82A586D27E53368BULL) ^ aNonceWordP;
            aOrbiterJ = RotL64((aOrbiterJ * 0xBB2D127CCF61506BULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x27341F5B3A5CAD15ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xD9FC81EF68DA4FB7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x72990FBC11C9BD73ULL), 11U);
