            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x1C790DDB6AD18771ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xD0240B7D563B55EFULL;
            aOrbiterA = RotL64((aOrbiterA * 0xDF06B0C7BCC864D7ULL), 29U);
