            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 3309U)) & S_BLOCK1], 60U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 2638U)) & S_BLOCK1], 21U));
