            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 3154U)) & S_BLOCK1], 21U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 3510U)) & S_BLOCK1], 57U));
