            //
            aScatter = (RotL64(aCarry, 60U) ^ RotL64(aPrevious, 27U)) ^ (RotL64(aCross, 39U) + RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 57U)) + RotL64(aCarry, 35U)) + 0xB2986796A1B10D90ULL;
            aOrbiterK = ((aWandererA + RotL64(aIngress, 3U)) + RotL64(aCarry, 53U)) + 0x342BA1C963C96A20ULL;
            aOrbiterI = ((aWandererH + RotL64(aCross, 27U)) + 0xC830AF01BC78D1A0ULL) + aPhaseCOrbiterAssignSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterB = ((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 5U)) + 0x195116F750E5DF31ULL;
            aOrbiterD = (aWandererF + RotL64(aCross, 13U)) + 0xADD53A39F53FA238ULL;
            aOrbiterF = (aWandererD + RotL64(aPrevious, 36U)) + 0x38896AF6EE410CE3ULL;
            aOrbiterG = ((aWandererG + RotL64(aIngress, 43U)) + 0x3E9A0368E1CC5C2FULL) + aPhaseCOrbiterAssignSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xFD9B9978541A0FEAULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0x59B650184F2C8C1EULL) ^ aPhaseCOrbiterUpdateSaltC[((aIndex + 12U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x332EF8CFB9CE8557ULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x318B6BF0814B7F14ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xB45817C19C7D26D7ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x46E0D13B225D9021ULL), 21U);
