            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x9058FCF3E9CFB881ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x44768267B1BD7048ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6F4BE8203DB3B4BFULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xC6AE147B67AC7A3BULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x58903B7F0C8CC768ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x87C267E74C2904E9ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x342B0280D8BBDB6EULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0x5BCB1880D88E84DDULL) ^ aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x349744DDBA1C9A6FULL), 29U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xA8DA62767C71B8BAULL) + aPhaseCOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0xDC4D7BE54C2766DCULL) ^ aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
