            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x0BCA3A6531A21F4EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x7974C5ED36CDE3FAULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5C46C212E8C9D03FULL), 47U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterD, 21U);
