            //
            aWandererJ = aWandererJ + (((RotL64(aCross, 23U) + aOrbiterB) + RotL64(aOrbiterI, 53U)) + aPhaseCWandererUpdateSaltB[(((31U - aIndex) + 4U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 41U) + RotL64(aOrbiterB, 3U)) + aOrbiterG);
            aWandererH = aWandererH + ((RotL64(aScatter, 3U) + RotL64(aOrbiterK, 28U)) + aOrbiterF);
            aWandererA = aWandererA ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterF, 39U)) + aOrbiterB);
            aWandererF = aWandererF + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterD, 11U)) + aOrbiterG) + RotL64(aCarry, 35U));
