            aIngress = (RotL64(aIceLaneB[((aIndex + 24072U)) & S_BLOCK1], 3U) ^ RotL64(aHeartLaneD[((aIndex + 23981U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aSpiritLaneB[((aIndex + 23226U)) & S_BLOCK1], 27U) ^ RotL64(aEarthLaneC[((aIndex + 19869U)) & S_BLOCK1], 56U));
            aIngress = TwistMix64::DiffuseA(aIngress);
