            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 18535U)) & S_BLOCK1], 5U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 17735U)) & S_BLOCK1], 42U));
            aCross ^= (RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 20252U)) & S_BLOCK1], 57U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 24162U)) & S_BLOCK1], 27U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCarry, 13U) ^ RotL64(aIngress, 56U)) + (RotL64(aPrevious, 29U) + RotL64(aCross, 43U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererK + RotL64(aCross, 56U)) + 0x538D7B0EA121AE9CULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 27U)) + 0xB66DFCA46B1B5FAEULL;
            aOrbiterH = ((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 53U)) + 0x24AF9C3B583282A3ULL;
            aOrbiterG = (((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 13U)) + 0xAED513B50D0F1AF8ULL) + aPhaseDOrbiterAssignSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = ((aWandererF + RotL64(aCross, 47U)) + RotL64(aCarry, 41U)) + 0x1BE7512DE4FA1EF7ULL;
            aOrbiterA = ((aWandererB + RotL64(aScatter, 13U)) + 0xCF6355CD5ACE1CF0ULL) + aPhaseDOrbiterAssignSaltF[((aIndex + 13U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aPrevious, 41U)) + 0x023C921E2CC39F83ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xB1B25F010E5FB4EAULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xBB2EBBE48EEB68A2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x21BCA0B8ACDF5951ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x9E1B575712F5F12DULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x727C3AE5C4E22A93ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x99B8A37A1CE731EBULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x14592433E3114407ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xCB53CAD38A63C5DDULL;
            aOrbiterA = RotL64((aOrbiterA * 0x19E071EC4C1333BFULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xEF04F98C5E916660ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xB9D456ACB5B26E98ULL) ^ aPhaseDOrbiterUpdateSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x218A8CFE2477BECFULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x7088B9E025F82611ULL) + aPhaseDOrbiterUpdateSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xE91EDEBD0F3032F7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x86A37E0669056609ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xE0C8943F88FA5A26ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xC0860D09B81C3E33ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x54DCD913E2B5F8CBULL), 41U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0x82910876D1D032AAULL) + aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x71CBCE533C8A52D2ULL) ^ aPhaseDOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x6868CEAEA5799889ULL), 11U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterI, 4U);
