            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aCross, 51U) + aOrbiterI) + RotL64(aOrbiterH, 47U)) + aPhaseDWandererUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aIngress, 3U) + RotL64(aOrbiterE, 29U)) + aOrbiterC) + aPhaseDWandererUpdateSaltA[((aIndex + 12U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 57U) + aOrbiterF) + RotL64(aOrbiterI, 19U));
            aWandererF = aWandererF + (((RotL64(aPrevious, 11U) + RotL64(aOrbiterA, 38U)) + aOrbiterI) + RotL64(aCarry, 57U));
            aWandererH = aWandererH ^ ((RotL64(aScatter, 39U) + aOrbiterH) + RotL64(aOrbiterA, 13U));
