            //
            aCross = (RotL64(aIceLaneB[((S_BLOCK1 - aIndex + 31486U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 31347U)) & S_BLOCK1], 51U));
