            //
            aScatter = (RotL64(aPrevious, 21U) + RotL64(aCarry, 53U)) ^ (RotL64(aCross, 35U) + RotL64(aIngress, 6U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = (aWandererA + RotL64(aIngress, 12U)) + 0x4D6706C49EB96EC8ULL;
            aOrbiterF = ((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 27U)) + 0x0DA74460E1DFBB78ULL;
            aOrbiterC = ((aWandererE + RotL64(aCross, 57U)) + RotL64(aCarry, 5U)) + 0xEABE05848C91C1A4ULL;
            aOrbiterB = ((aWandererF + RotL64(aPrevious, 21U)) + RotL64(aCarry, 47U)) + 0x21C6BB460326D111ULL;
            aOrbiterD = ((aWandererI + RotL64(aScatter, 27U)) + 0xC270CEBB9836DF36ULL) + aPhaseBOrbiterAssignSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterJ = (aWandererC + RotL64(aCross, 41U)) + 0x70F83FBA55C6AC2BULL;
            aOrbiterG = ((aWandererG + RotL64(aIngress, 5U)) + 0x4A84A5D34F82BE3AULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 17U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xDB12B46227EECD92ULL;
