            aOrbiterC = RotL64((aOrbiterC * 0x9EEDD16F08E03FA1ULL), 39U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x46E0EC2EDF4E2477ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0xF47F3A54AD056DC7ULL) ^ aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x71683F06F13B31BDULL), 53U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x44DD8442907E6C28ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x4DDC60EC49E7DCC0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x69191D10CEA44DF1ULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x0377EAB892C5DF52ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x025ECDAE9FAD36E9ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x6365E633072F844DULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0x36103309E0F73A0DULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0x5AB4AF2E02C43BB2ULL) ^ aPhaseBOrbiterUpdateSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x6C0ED907DE43110BULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xBBEAA08F4EBB81C8ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xA8DF697C609BDF4DULL) ^ aPhaseBOrbiterUpdateSaltF[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xAEE62CB789CF4CF7ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x167C23F8BFBC4C07ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0xB115588AC8B57536ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2277DE8B0433CCB5ULL), 47U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterJ, 11U);
