            aIngress = aIngress + (RotL64(aOrbiterG, 35U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterC, 43U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererG = aWandererG + ((((RotL64(aPrevious, 53U) + aOrbiterB) + RotL64(aOrbiterD, 11U)) + RotL64(aCarry, 27U)) + aPhaseBWandererUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 3U) + RotL64(aOrbiterG, 47U)) + aOrbiterB);
